void restState(unsigned long now) {
    display.fillScreen(0);

    // Persistent state variables
    static float corePulse = 0.0f;
    static unsigned long lastTime = 0;

    // Structs and constants for particles (overflowing energy)
    struct Drop {
        float x, y;
        float vx, vy;
        float life;
        float maxLife;
        uint8_t baseR, baseG, baseB;
    };

    const int MAX_DROPS = 16;
    static Drop drops[MAX_DROPS];
    static bool initialized = false;

    unsigned long dt = now - lastTime;
    if (dt > 100) dt = 16; // Cap delta time
    lastTime = now;
    float seconds = dt / 1000.0f;

    if (!initialized) {
        for (int i = 0; i < MAX_DROPS; i++) {
            drops[i].life = -1.0f; // inactive
        }
        initialized = true;
    }

    // Animate core pulse (heartbeat rhythm)
    corePulse += seconds * 4.0f;
    float heartbeat = (sin(corePulse) * 0.5f + 0.5f); // 0.0 to 1.0
    float scale = 1.0f + heartbeat * 0.15f;          // subtle size pulsing

    // 1. Draw the overflowing heart (Center at 15.5, 16)
    // We iterate through a 32x32 bounding box and evaluate heart inequality
    for (int y = 0; y < 32; y++) {
        for (int x = 0; x < 32; x++) {
            // Normalize coordinates to roughly -1.1 to 1.1
            float nx = (x - 15.5f) / (11.0f * scale);
            float ny = (y - 17.0f) / (11.0f * scale);

            // Heart equation: (x^2 + y^2 - 1)^3 - x^2 * y^3 <= 0
            float xx = nx * nx;
            float yy = ny * ny;
            float term = xx + yy - 1.0f;
            float val = (term * term * term) - (xx * ny * yy * ny);

            if (val <= 0.0f) {
                // Inside heart: vibrant deep pink to glowing magenta/red
                // Brighter at the center, glowing edge
                float depthFactor = 1.0f - (val / -2.0f);
                if (depthFactor < 0.2f) depthFactor = 0.2f;
                if (depthFactor > 1.0f) depthFactor = 1.0f;

                float brightness = 0.4f + 0.6f * heartbeat * depthFactor;

                // Rich magenta-red color scaled by brightness
                int r = (int)(255 * brightness);
                int g = (int)((20 + 40 * heartbeat) * brightness);
                int b = (int)((100 + 100 * depthFactor) * brightness);

                r = r > 255 ? 255 : (r < 0 ? 0 : r);
                g = g > 255 ? 255 : (g < 0 ? 0 : g);
                b = b > 255 ? 255 : (b < 0 ? 0 : b);

                display.drawPixel(x, y, display.color565(r, g, b));
            }
        }
    }

    // 2. Spawn overflow particles from the top cleft of the heart (around x=15, y=10)
    static float spawnTimer = 0.0f;
    spawnTimer += seconds;
    if (spawnTimer > 0.15f) {
        spawnTimer = 0.0f;
        // Find dead drop and respawn
        for (int i = 0; i < MAX_DROPS; i++) {
            if (drops[i].life <= 0.0f) {
                drops[i].x = 15.0f + (float)(rand() % 5 - 2) * 0.5f;
                drops[i].y = 10.0f;
                // Upward/outward burst, then gravity pulls down
                drops[i].vx = (float)(rand() % 20 - 10) * 0.1f;
                drops[i].vy = -1.5f - (float)(rand() % 10) * 0.1f;
                drops[i].life = 1.0f;
                drops[i].maxLife = 1.0f + (float)(rand() % 10) * 0.1f;
                drops[i].baseR = 255;
                drops[i].baseG = 120 + (rand() % 100);
                drops[i].baseB = 220;
                break;
            }
        }
    }

    // 3. Update and draw particles (overflowing giving essence)
    for (int i = 0; i < MAX_DROPS; i++) {
        if (drops[i].life > 0.0f) {
            drops[i].x += drops[i].vx * seconds * 15.0f;
            drops[i].y += drops[i].vy * seconds * 15.0f;
            drops[i].vy += 2.5f * seconds; // gravity/pull

            drops[i].life -= seconds / drops[i].maxLife;

            int px = (int)(drops[i].x + 0.5f);
            int py = (int)(drops[i].y + 0.5f);

            if (px >= 0 && px < 32 && py >= 0 && py < 32) {
                float fade = drops[i].life; // 1.0 down to 0.0
                if (fade < 0.0f) fade = 0.0f;

                int r = (int)(drops[i].baseR * fade);
                int g = (int)(drops[i].baseG * fade);
                int b = (int)(drops[i].baseB * fade);

                r = r > 255 ? 255 : (r < 0 ? 0 : r);
                g = g > 255 ? 255 : (g < 0 ? 0 : g);
                b = b > 255 ? 255 : (b < 0 ? 0 : b);

                display.drawPixel(px, py, display.color565(r, g, b));
            }
        }
    }
}
